per\",\"id\":\"s1_3533\",\"timestamp\":1794463717},{\"recordedBy\":\"Simondruid-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Al'Aketh Stormcaller\"},\"event\":\"CHAT_MSG_MONSTER_EMOTE\",\"type\":\"MONSTER_EMOTE\"},\"color\":{\"b\":0.250980406999588,\"g\":0.501960813999176,\"r\":1},\"text\":\"Al'Aketh Stormcaller attempts to run away in fear!\",\"id\":\"s1_3534\",\"timestamp\":1794463737},{\"recordedBy\":\"Simondruid-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Al'Aketh Stormcaller\"},\"event\":\"CHAT_MSG_MONSTER_EMOTE\",\"type\":\"MONSTER_EMOTE\"},\"color\":{\"b\":0.250980406999588,\"g\":0.501960813999176,\"r\":1},\"text\":\"Al'Aketh Stormcaller attempts to run away in fear!\",\"id\":\"s1_3535\",\"timestamp\":1794463777},{\"recordedBy\":\"Simondruid-Windseeker\",\"typeInfo\":{\"event\":\"CHAT_MSG_SKILL\",\"type\":\"SKILL\"},\"color\":{\"b\":1,\"g\":0.3333333432674408,\"r\":0.3333333432674408},\"text\":\"Your skill in Defense has increased to 40.\",\"id\":\"s1_3536\",\"timestamp\":1794463795},{\"recordedBy\":\"Simondruid-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Commander Cyclas\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"b\":0.6235294342041016,\"g\":1,\"r\":1},\"text\":\"Commander Cyclas says: Only the righteous will be saved from what is to come! Death to non-believers!\",\"id\":\"s1_3537\",\"timestamp\":1794463796},{\"recordedBy\":\"Simondruid-Windseeker\",\"typeInfo\":{\"event\":\"CHAT_MSG_SKILL\",\"type\":\"SKILL\"},\"color\":{\"b\":1,\"g\":0.3333333432674408,\"r\":0.3333333432674408},\"text\":\"Your skill in Daggers has increased to 35.\",\"id\":\"s1_3538\",\"timestamp\":1794463807},{\"recordedBy\":\"Simondruid-Windseeker\",\"typeInfo\":{\"player\":{\"race\":\"Skyborne\",\"name\":\"Simondruid Windseeker\",\"sex\":3,\"class\":\"DRUID\",\"level\":9},\"event\":\"CHAT_MSG_LOOT\",\"type\":\"LOOT\"},\"color\":{\"b\":0,\"g\":0.6666666865348816,\"r\":0},\"text\":\"You receive loot: |cnIQ1:|Hitem:252661::::::::9:1484:::