mestamp\":1794630048},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"race\":\"Skyborne\",\"name\":\"Simonrogue Windseeker\",\"sex\":3,\"class\":\"ROGUE\",\"level\":13},\"event\":\"CHAT_MSG_LOOT\",\"type\":\"LOOT\"},\"color\":{\"b\":0,\"g\":0.6666666865348816,\"r\":0},\"text\":\"You receive loot: |cnIQ2:|Hitem:10938::::::::13:1488:::::::::|h[Lesser Magic Essence]|h|r\",\"id\":\"s3_3193\",\"timestamp\":1794630049},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"event\":\"CHAT_MSG_MONEY\",\"type\":\"MONEY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0},\"text\":\"You loot 2 Copper\",\"timestamp\":1794630286,\"id\":\"s3_3194\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"race\":\"Skyborne\",\"name\":\"Simonrogue Windseeker\",\"sex\":3,\"class\":\"ROGUE\",\"level\":13},\"event\":\"CHAT_MSG_LOOT\",\"type\":\"LOOT\"},\"color\":{\"r\":0,\"g\":0.6666666865348816,\"b\":0},\"text\":\"You receive loot: |cnIQ1:|Hitem:252031::::::::13:1488:::::::::|h[Crisp Spring Water]|h|r\",\"timestamp\":1794630298,\"id\":\"s3_3195\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"event\":\"CHAT_MSG_MONEY\",\"type\":\"MONEY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0},\"text\":\"You loot 34 Copper\",\"timestamp\":1794630299,\"id\":\"s3_3196\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"event\":\"CHAT_MSG_MONEY\",\"type\":\"MONEY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0},\"text\":\"You loot 3 Copper\",\"timestamp\":1794630304,\"id\":\"s3_3197\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"race\":\"Skyborne\",\"name\":\"Simonrogue Windseeker\",\"sex\":3,\"class\":\"ROGUE\",\"level\":13},\"event\":\"CHAT_MSG_LOOT\",\"type\":\"LOOT\"},\"color\":{\"r\":0,\"g\":0.6666666865348816,\"b\":0},\"text\":\"You receive loot: |cnIQ1:|Hitem:1181::::::::13:1488:::::::::|h[Scroll of Spirit]|h|r\",\"timestamp\":1794630314,\"id\":\"s3_3198\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"event\":\"CHAT_MSG_MONEY\",\"type\":\"MONEY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0},\"text\":\"You loot 10 Copper\",\"timestamp\":1794630315,\"id\":\"s3_3199\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"race\":\"Skyborne\",\"name\":\"Simonrogue Windseeker\",\"sex\":3,\"class\":\"ROGUE\",\"level\":13},\"event\":\"CHAT_MSG_LOOT\",\"type\":\"LOOT\"},\"color\":{\"r\":0,\"g\":0.6666666865348816,\"b\":0},\"text\":\"You receive item: |cnIQ1:|Hitem:273852::::::::13:1488:::::::::|h[Glowing Crystal]|h|r\",\"timestamp\":1794630318,\"id\":\"s3_3200\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Vuldren Alpha\"},\"event\":\"CHAT_MSG_MONSTER_EMOTE\",\"type\":\"MONSTER_EMOTE\"},\"color\":{\"r\":1,\"g\":0.501960813999176,\"b\":0.250980406999588},\"text\":\"Vuldren Alpha becomes enraged!\",\"timestamp\":1794630432,\"id\":\"s3_3201\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"race\":\"Skyborne\",\"name\":\"Simonrogue Windseeker\",\"sex\":3,\"class\":\"ROGUE\",\"level\":13},\"event\":\"CHAT_MSG_LOOT\",\"type\":\"LOOT\"},\"color\":{\"r\":0,\"g\":0.6666666865348816,\"b\":0},\"text\":\"You receive loot: |cnIQ1:|Hitem:2672::::::::13:1488:::::::::|h[Stringy Wolf Meat]|h|r\",\"timestamp\":1794630437,\"id\":\"s3_3202\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"race\":\"Skyborne\",\"name\":\"Simonrogue Windseeker\",\"sex\":3,\"class\":\"ROGUE\",\"level\":13},\"event\":\"CHAT_MSG_LOOT\",\"type\":\"LOOT\"},\"color\":{\"r\":0,\"g\":0.6666666865348816,\"b\":0},\"text\":\"You receive loot: |cnIQ0:|Hitem:3300::::::::13:1488:::::::::|h[Rabbit's Foot]|h|r\",\"timestamp\":1794630437,\"id\":\"s3_3203\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"race\":\"Skyborne\",\"name\":\"Simonrogue Windseeker\",\"sex\":3,\"class\":\"ROGUE\",\"level\":13},\"event\":\"CHAT_MSG_LOOT\",\"type\":\"LOOT\"},\"color\":{\"r\":0,\"g\":0.6666666865348816,\"b\":0},\"text\":\"You receive loot: |cnIQ1:|Hitem:2934::::::::13:1488:::::::::|h[Ruined Leather Scraps]|h|r\",\"timestamp\":1794630441,\"id\":\"s3_3204\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"race\":\"Skyborne\",\"name\":\"Simonrogue Windseeker\",\"sex\":3,\"class\":\"ROGUE\",\"level\":13},\"event\":\"CHAT_MSG_LOOT\",\"type\":\"LOOT\"},\"color\":{\"r\":0,\"g\":0.6666666865348816,\"b\":0},\"text\":\"You receive item: |cnIQ2:|Hitem:263330::::::::13:1488::11:::::::|h[Tracker's Pants]|h|r\",\"timestamp\":1794630505,\"id\":\"s3_3205\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Talaanis Shadowsong\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"Talaanis Shadowsong says: Wait, yes... this crystal! Valennia, is this...\",\"timestamp\":1794630519,\"id\":\"s3_3206\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Valennia Stormfist\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"Valennia Stormfist says: ...a recall crystal! Used to record an important moment, no doubt.\",\"timestamp\":1794630523,\"id\":\"s3_3207\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Talaanis Shadowsong\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"Talaanis Shadowsong says: This is surely what the turncoat hoped to offer us in exchange for our protection.\",\"timestamp\":1794630527,\"id\":\"s3_3208\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Valennia Stormfist\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"Valennia Stormfist says: The recall crystal is badly damaged, though. The recording is likely to be incomplete, so we must listen carefully.\",\"timestamp\":1794630533,\"id\":\"s3_3209\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Talaanis Shadowsong\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"Talaanis Shadowsong says: Activate it, Valennia. We need to learn as much as we can about what it contains.\",\"timestamp\":1794630541,\"id\":\"s3_3210\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"High Priestess Lorthuna\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"High Priestess Lorthuna says: ...do not delay. Muster our forces to march immediately. The pylons are key and...the wards...come down. This is...\",\"timestamp\":1794630551,\"id\":\"s3_3211\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"High Priestess Lorthuna\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"High Priestess Lorthuna says: ...quickly. With our forces.....will be exposed.....my ritual must not....\",\"timestamp\":1794630556,\"id\":\"s3_3212\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"High Priestess Lorthuna\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"High Priestess Lorthuna says: I alone am.....this task....the Windlord will.......our voices.....he will come.....we must not fail!\",\"timestamp\":1794630563,\"id\":\"s3_3213\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Valennia Stormfist\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"Valennia Stormfist says: The crystal is too damaged to play any further, I am afraid.\",\"timestamp\":1794630571,\"id\":\"s3_3214\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Talaanis Shadowsong\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"Talaanis Shadowsong says: Wards... what is this about wards, Valennia?\",\"timestamp\":1794630577,\"id\":\"s3_3215\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Valennia Stormfist\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"Valennia Stormfist says: The anchor pylons keep us suspended in this realm, but they also act as wards! The Shal'nan once spoke of this. They keep us shielded from...\",\"timestamp\":1794630581,\"id\":\"s3_3216\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Talaanis Shadowsong\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"Talaanis Shadowsong says: ...whatever else is out there in Skywall. Spirits save us... this is her plan. Bring down the wards and let her 'Windlord' in!\",\"timestamp\":1794630591,\"id\":\"s3_3217\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Valennia Stormfist\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"Valennia Stormfist says: With the cult running roughshod over most of the island with impunity, Lorthuna undoubtedly thinks we are on the back foot. We can use that overconfidence against her.\",\"timestamp\":1794630684,\"id\":\"s3_3218\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Valennia Stormfist\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"Valennia Stormfist says: I believe that with a proper distraction at the shrine, a small force of Peacekeepers, Windshapers, and High Order should be able to push up a flank and break into the inner sanctum. From there, we take out the High Priestess herself and cut the head off the snake.\",\"timestamp\":1794630693,\"id\":\"s3_3219\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Valennia Stormfist\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"Valennia Stormfist says: Go and speak with the leaders of the Windshapers and the High Order, respectively. They don't get along, but I think they can recognize that the bigger threat is the Al'Aketh. Get them to agree to the plan and then return here.\",\"timestamp\":1794630708,\"id\":\"s3_3220\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Ayessa Dawnsinger\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"Ayessa Dawnsinger says: Inquiry? You mean his thinly veiled threat? You go back and tell Elaadrin that if he has something to say, he can come and speak to me himself.\",\"timestamp\":1794630761,\"id\":\"s3_3221\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"High Order Messenger\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"High Order Messenger says: Skyseer, need I remind you that High Order blood has been spilled? We would have those responsible answer for this crime.\",\"timestamp\":1794630769,\"id\":\"s3_3222\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Ayessa Dawnsinger\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"Ayessa Dawnsinger says: Oh, that's rich, little mage. What of the Windshapers that your agent killed in the highlands? Who will answer for them?\",\"timestamp\":1794630776,\"id\":\"s3_3223\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"High Order Mage\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"High Order Mage says: Watch yourself. The High Order will not tolerate hostility in our lodge.\",\"timestamp\":1794630855,\"id\":\"s3_3224\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"event\":\"CHAT_MSG_COLLECTED_APPEARANCE\",\"type\":\"COLLECTED_APPEARANCE\"},\"color\":{\"r\":1,\"g\":1,\"b\":0},\"text\":\"|cffff80ff|Hitem:4561|h[Scalping Tomahawk]|h|r has been added to your appearance collection.\",\"timestamp\":1794630914,\"id\":\"s3_3225\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"race\":\"Skyborne\",\"name\":\"Simonrogue Windseeker\",\"sex\":3,\"class\":\"ROGUE\",\"level\":13},\"event\":\"CHAT_MSG_LOOT\",\"type\":\"LOOT\"},\"color\":{\"r\":0,\"g\":0.6666666865348816,\"b\":0},\"text\":\"You receive item: |cnIQ2:|Hitem:257344::::::::13:1488::11:::::::|h[Skywatcher's Vestments]|h|r\",\"timestamp\":1794630946,\"id\":\"s3_3226\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Elaadrin Evengale\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"Elaadrin Evengale says: We came as soon as we were told what was happening. The High Order is here to serve Zephras.\",\"timestamp\":1794631012,\"id\":\"s3_3227\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Ayessa Dawnsinger\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"Ayessa Dawnsinger says: ...and the Windshapers. We are ready to support an assault on the Shrine, Valennia.\",\"timestamp\":1794631018,\"id\":\"s3_3228\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Valennia Stormfist\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"Valennia Stormfist says: You have my thanks. Being truthful, however, this is going to be a dangerous gambit and we may not succeed. It's important you understand that this might be a one-way ride.\",\"timestamp\":1794631023,\"id\":\"s3_3229\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Ayessa Dawnsinger\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0.6235294342041016},\"text\":\"Ayessa Dawnsinger says: We understand. As it happens Elaadrin and I spoke. We made arrangements to send for... outside aid. It's unclear if they will be able to arrive in time to help, or if they will even arrive at all...\",\"timestamp\":1794631033,\"id\":\"s3_3230\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"event\":\"CHAT_MSG_MONEY\",\"type\":\"MONEY\"},\"color\":{\"r\":1,\"g\":1,\"b\":0},\"text\":\"You loot 1 Copper\",\"timestamp\":1794631157,\"id\":\"s3_3231\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Al'Aketh Spiritcaller\"},\"event\":\"CHAT_MSG_MONSTER_EMOTE\",\"type\":\"MONSTER_EMOTE\"},\"color\":{\"r\":1,\"g\":0.501960813999176,\"b\":0.250980406999588},\"text\":\"Al'Aketh Spiritcaller attempts to run away in fear!\",\"timestamp\":1794631164,\"id\":\"s3_3232\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"race\":\"Skyborne\",\"name\":\"Simonrogue Windseeker\",\"sex\":3,\"class\":\"ROGUE\",\"level\":13},\"event\":\"CHAT_MSG_LOOT\",\"type\":\"LOOT\"},\"color\":{\"r\":0,\"g\":0.6666666865348816,\"b\":0},\"text\":\"You receive loot: |cnIQ1:|Hitem:255663::::::::13:1488:::::::::|h[Windstone]|h|rx2\",\"timestamp\":1794631167,\"id\":\"s3_3233\"},{\"recordedBy\":\"Simonrogue-Windseeker\",\"typeInfo\":{\"player\":{\"race\":\"Skyborne\",\"name\":\"Simonrogue Windseeker\",\"sex\":3,\"class\"